const PRACTICE_KEY='learning-garden-practice-v1';
const PRACTICE_TOPICS={all:'Mixed basics',variables:'Variables & values',functions:'Functions',logic:'If & logic',loops:'Loops',strings:'Strings',lists:'Lists & sets'};
const PRACTICE_BANK=window.GARDEN_PRACTICE_QUESTIONS;
const PRACTICE_LINKS=[['CodingBat','Small beginner exercises','https://codingbat.com/python'],['Exercism','Structured Python practice','https://exercism.org/tracks/python'],['CodeCombat','Game-style coding','https://codecombat.com/'],['Codewars','Coding challenges','https://www.codewars.com/'],['HackerRank','Topic-based Python problems','https://www.hackerrank.com/domains/python'],['Python Arena','Your saved practice reference','https://pythonarena.org/'],['CheckiO','Python puzzle missions','https://checkio.org/']];
let practiceState={topic:'functions',draft:null,checks:[],tests:[],activeTestId:''},practiceStorageOK=true,practiceWindow='practice';
function practiceDay(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function practiceQuestion(id){return PRACTICE_BANK.find(q=>q.id===id)}
function normalizePracticeAnswer(v){return String(v??'').replace(/\r\n/g,'\n').trim().split('\n').map(x=>x.trim()).join('\n')}
function practiceCorrect(q,answer){return q.type==='choice'?String(answer)===String(q.answer):normalizePracticeAnswer(answer)===normalizePracticeAnswer(q.answer)}
function testScore(test){return test.qids.reduce((n,id)=>n+(practiceCorrect(practiceQuestion(id),test.answers[id])?1:0),0)}
function validatePracticeState(v){if(!v||typeof v!=='object'||!Array.isArray(v.checks)||!Array.isArray(v.tests)||v.checks.length>10000||v.tests.length>2000)throw Error('Invalid practice history');const ids=new Set();const date=d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&!Number.isNaN(Date.parse(d+'T00:00:00Z'))&&new Date(d+'T00:00:00Z').toISOString().slice(0,10)===d;const checks=v.checks.map(c=>{if(!c||typeof c.id!=='string'||ids.has(c.id)||!practiceQuestion(c.qid)||!date(c.date)||typeof c.answer!=='string'||c.answer.length>2000)throw Error('Invalid practice attempt');ids.add(c.id);return {...c,correct:practiceCorrect(practiceQuestion(c.qid),c.answer),helped:!!c.helped}});const tests=v.tests.map(t=>{if(!t||typeof t.id!=='string'||ids.has(t.id)||!date(t.date)||!Object.hasOwn(PRACTICE_TOPICS,t.topic)||!Array.isArray(t.qids)||t.qids.length!==5||new Set(t.qids).size!==5||!t.qids.every(practiceQuestion)||!t.answers||typeof t.answers!=='object'||!['active','submitted','abandoned'].includes(t.status))throw Error('Invalid test');ids.add(t.id);const answers={};for(const id of t.qids){if(t.answers[id]!==undefined){if(typeof t.answers[id]!=='string'||t.answers[id].length>2000)throw Error('Invalid answer');answers[id]=t.answers[id]}}const fixed={...t,answers,index:Math.max(0,Math.min(4,Number(t.index)||0))};fixed.score=t.status==='submitted'?testScore(fixed):null;return fixed});let draft=null;if(v.draft&&practiceQuestion(v.draft.qid))draft={qid:v.draft.qid,answer:String(v.draft.answer||'').slice(0,2000),hint:!!v.draft.hint,checked:!!v.draft.checked,revealed:!!v.draft.revealed};return {topic:Object.hasOwn(PRACTICE_TOPICS,v.topic)?v.topic:'functions',draft,checks,tests,activeTestId:tests.some(t=>t.id===v.activeTestId)?v.activeTestId:''}}
try{const s=localStorage.getItem(PRACTICE_KEY);if(s)practiceState=validatePracticeState(JSON.parse(s))}catch{practiceStorageOK=false}
function persistPractice(){try{localStorage.setItem(PRACTICE_KEY,JSON.stringify(practiceState));practiceStorageOK=true}catch{practiceStorageOK=false}}
function mergePracticeState(incoming){if(!incoming)return;const byId=(a,b)=>[...new Map([...a,...b].map(x=>[x.id,x])).values()];practiceState={...practiceState,checks:byId(practiceState.checks,incoming.checks),tests:byId(practiceState.tests,incoming.tests)};persistPractice()}
function practicePool(){return PRACTICE_BANK.filter(q=>practiceState.topic==='all'||q.topic===practiceState.topic)}
function shuffledPractice(pool,seed){let x=0;for(const c of seed)x=(Math.imul(x,31)+c.charCodeAt(0))>>>0;const out=[...pool];for(let i=out.length-1;i>0;i--){x=(Math.imul(x,1664525)+1013904223)>>>0;const j=x%(i+1);[out[i],out[j]]=[out[j],out[i]]}return out}
function currentPracticeDraft(){if(!practiceState.draft||!practicePool().some(q=>q.id===practiceState.draft.qid)){const q=shuffledPractice(practicePool(),practiceDay()+practiceState.topic)[0];practiceState.draft={qid:q.id,answer:'',hint:false,checked:false,revealed:false};persistPractice()}return practiceState.draft}
function activePracticeTest(){return practiceState.tests.find(t=>t.id===practiceState.activeTestId)}
function unresolvedPracticeMistakes(){const events=[...practiceState.checks.map(c=>({time:c.createdAt||c.date,results:[[c.qid,c.correct]]})),...practiceState.tests.filter(t=>t.status==='submitted').map(t=>({time:t.endedAt||t.date,results:t.qids.map(id=>[id,practiceCorrect(practiceQuestion(id),t.answers[id])])}))].sort((a,b)=>a.time.localeCompare(b.time));const missed=new Set();events.forEach(e=>e.results.forEach(([id,ok])=>ok?missed.delete(id):missed.add(id)));return [...missed]}
function practiceStreak(){const days=new Set([...practiceState.checks.map(c=>c.date),...practiceState.tests.filter(t=>t.status==='submitted').map(t=>t.date)]);let date=practiceDay(),count=0;if(!days.has(date))date=new Date(Date.parse(date+'T00:00:00Z')-86400000).toISOString().slice(0,10);while(days.has(date)){count++;date=new Date(Date.parse(date+'T00:00:00Z')-86400000).toISOString().slice(0,10)}return count}
function practiceAnswerLabel(q,answer){if(answer===undefined||answer==='')return 'Not answered';return q.type==='choice'?q.choices[Number(answer)]||'Not answered':answer}
function practiceAnswerInput(q,answer,mode){return q.type==='choice'?`<fieldset class="practice-options"><legend class="sr-only">Choose your answer</legend>${q.choices.map((c,i)=>`<label><input type="radio" name="${mode}Answer" data-practice-answer="${mode}" value="${i}" ${String(answer)===String(i)?'checked':''}><span>${esc(c)}</span></label>`).join('')}</fieldset>`:`<label for="${mode}Answer">${q.answer.includes('\n')?'Output (one result per line)':'Your answer — exactly as printed'}</label><textarea id="${mode}Answer" data-practice-answer="${mode}" rows="${q.answer.includes('\n')?'3':'2'}" maxlength="2000" placeholder="Type the output here…" spellcheck="false">${esc(answer||'')}</textarea>`}
function renderPractice(){const today=practiceDay(),checked=practiceState.checks.filter(c=>c.date===today),tests=practiceState.tests.filter(t=>t.status==='submitted'),last=[...tests].sort((a,b)=>(b.endedAt||b.date).localeCompare(a.endedAt||a.date))[0],missed=unresolvedPracticeMistakes();$('breadcrumb').textContent='Practise / Test';$('search').placeholder='Search your learning garden…';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view==='practice'));const weekday=new Date(today+'T12:00:00Z').getUTCDay();const schedule=[['Review mistakes','Retry the questions that felt tricky.',''],['CodingBat','20 minutes · small exercises','https://codingbat.com/python'],['Kaggle exercises','20 minutes · apply your lesson','https://www.kaggle.com/learn/intro-to-programming'],['CodingBat','20 minutes · build confidence','https://codingbat.com/python'],['Exercism','25 minutes · structured practice','https://exercism.org/tracks/python'],['CodeCombat','20 minutes · make it playful','https://codecombat.com/'],['HackerRank or Codewars','30 minutes · one manageable challenge','https://www.hackerrank.com/domains/python']][weekday];$('content').innerHTML=`<div class="intro"><div><h1>A little practice. A little proof.</h1><p class="muted">Make room for one small challenge, every day.</p></div><label class="practice-topic-label" for="practiceTopic">My topic<select id="practiceTopic">${Object.entries(PRACTICE_TOPICS).map(([k,v])=>`<option value="${k}" ${practiceState.topic===k?'selected':''}>${v}</option>`).join('')}</select></label></div><div class="practice-mini-stats"><div><strong>${new Set(checked.map(c=>c.qid)).size}</strong><span>questions tried today</span></div><div><strong>${tests.filter(t=>t.date===today).length}</strong><span>tests finished today</span></div><div><strong>${practiceStreak()}</strong><span>day${practiceStreak()===1?'':'s'} of consistency</span></div></div><div class="practice-windows"><section class="practice-launch practice-blue"><span class="practice-doodle" aria-hidden="true">✳</span><span class="tag">LEARN BY TRYING</span><h2>Practise.</h2><p>Take your time. Try a question, ask for a hint, and see why an answer works.</p><div class="practice-launch-bottom"><small>${practicePool().length} original questions · ${PRACTICE_TOPICS[practiceState.topic]}</small><button class="primary" id="openPractice">Open practice ↗</button></div></section><section class="practice-launch practice-pink"><span class="practice-doodle" aria-hidden="true">✦</span><span class="tag">CHECK WHAT STUCK</span><h2>Test yourself.</h2><p>Five questions. No hints until you submit. A score and a useful review at the end.</p><div class="practice-launch-bottom"><small>${last?'Last result: '+last.score+'/5':'Untimed · no pressure to rush'}</small><button class="primary" id="openTest">${activePracticeTest()?.status==='active'?'Continue test ↗':'Open test ↗'}</button></div></section></div><p class="learning-hint">Built-in exercises check concepts and predicted output; they do not run arbitrary Python code. Use the platforms below to write and run full programs.</p><div class="practice-shortcuts" aria-label="Direct Python practice links"><a href="https://codingbat.com/python" target="_blank" rel="noopener noreferrer"><span>CodingBat · Python</span><strong>Practise now ↗</strong></a><a href="https://exercism.org/tracks/python" target="_blank" rel="noopener noreferrer"><span>Exercism · Python track</span><strong>Open exercises ↗</strong></a></div><div class="practice-daily"><div><span class="tag">TODAY’S LITTLE ROUTINE</span><h3>${schedule[0]}</h3><p>${schedule[1]}</p></div>${schedule[2]?`<a class="practice-link-button" href="${schedule[2]}" target="_blank" rel="noopener noreferrer">Open platform ↗</a>`:`<button data-practice-retry="true" ${!missed.length?'disabled':''}>Retry mistakes (${missed.length}) ↗</button>`}</div><details class="practice-resources"><summary>Your Python practice platforms <span>7 bookmarks ↗</span></summary><div class="practice-platform-grid">${PRACTICE_LINKS.map(([name,description,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer"><strong>${name} ↗</strong><span>${description}</span></a>`).join('')}</div><p class="learning-hint">External platforms open in new tabs. Their accounts and progress stay on those platforms.</p></details><div class="section-head"><h2>Small steps, recorded.</h2><button data-practice-retry="true" class="textbtn" ${!missed.length?'disabled':''}>Retry mistakes · ${missed.length}</button></div><div class="practice-history">${tests.slice().sort((a,b)=>(b.endedAt||b.date).localeCompare(a.endedAt||a.date)).slice(0,7).map(t=>`<button data-practice-result="${esc(t.id)}"><span>${taskDate(t.date)}<small>${PRACTICE_TOPICS[t.topic]}</small></span><strong>${t.score}/5 ↗</strong></button>`).join('')||'<p class="muted">Your completed tests will appear here. Start with one when you feel ready.</p>'}</div><footer><span>${practiceStorageOK?'Progress saves in this browser and is included in your backup.':'Storage is unavailable. Export a backup to keep your progress.'} No AI API calls.</span><span><button class="textbtn" id="export">Export backup ↓</button><button class="textbtn" id="import">Import backup ↑</button></span></footer>`}
function renderPracticeWindow(){const draft=currentPracticeDraft(),q=practiceQuestion(draft.qid),ok=practiceCorrect(q,draft.answer);$('practiceDialogContent').innerHTML=`<div class="section-head" style="margin-top:0"><div><span class="tag">${PRACTICE_TOPICS[q.topic]}</span><h2>One question at a time.</h2></div><button data-close-practice="practiceDialog" aria-label="Close practice">✕</button></div><h3>${esc(q.prompt)}</h3>${q.code?`<pre class="practice-code"><code>${esc(q.code)}</code></pre>`:''}${practiceAnswerInput(q,draft.answer,'practice')}<div class="practice-controls"><button id="practiceHint">${draft.hint?'Hide hint':'A little hint'}</button><button id="practiceCheck" class="primary">Check answer</button></div>${draft.hint?`<p class="practice-hint">${esc(q.hint)}</p>`:''}${draft.checked?`<div class="practice-feedback ${ok?'correct':'retry'}" role="status"><strong>${ok?'That’s right.':'Not quite yet. Try tracing it one line at a time.'}</strong>${ok?`<p>${esc(q.explanation)}</p>`:''}</div>`:''}${draft.revealed?`<div class="practice-solution"><strong>Answer</strong><pre>${esc(practiceAnswerLabel(q,String(q.answer)))}</pre><p>${esc(q.explanation)}</p></div>`:''}<div class="actions"><button id="practiceSolution">${draft.revealed?'Hide solution':'Show solution'}</button><button id="practiceNext">Next question ↗</button></div>`}
function startPracticeTest(){let test=practiceState.tests.find(t=>t.status==='active');if(test){practiceState.activeTestId=test.id;persistPractice();return test;}const round=practiceState.tests.filter(t=>t.date===practiceDay()&&t.topic===practiceState.topic).length;test={id:newId(),date:practiceDay(),topic:practiceState.topic,qids:shuffledPractice(practicePool(),practiceDay()+practiceState.topic+round).slice(0,5).map(q=>q.id),answers:{},index:0,status:'active',score:null,createdAt:new Date().toISOString()};practiceState.tests.push(test);practiceState.activeTestId=test.id;persistPractice();return test}
function renderTestWindow(){const test=activePracticeTest();if(!test)return;const done=test.status==='submitted';$('testDialogContent').innerHTML=`<div class="section-head" style="margin-top:0"><div><span class="tag">${PRACTICE_TOPICS[test.topic]}</span><h2>${done?'Look at what you learned.':'Your five-question check-in.'}</h2></div><button data-close-practice="testDialog" aria-label="Close test">✕</button></div>${done?`<div class="test-score"><strong>${test.score}<small>/5</small></strong><div><h3>${test.score===5?'A lovely little win.':'Good information for your next practice.'}</h3><p>${taskDate(test.date)} · ${Math.round(test.score/5*100)}% correct</p></div></div><div class="test-review">${test.qids.map((id,i)=>{const q=practiceQuestion(id),ok=practiceCorrect(q,test.answers[id]);return `<details><summary><span class="${ok?'answer-right':'answer-wrong'}">${ok?'✓':'↻'}</span> ${i+1}. ${esc(q.prompt)}<small>${ok?'Correct':'Revisit'}</small></summary><pre class="practice-code"><code>${esc(q.code)}</code></pre><p>Your answer: <code>${esc(practiceAnswerLabel(q,test.answers[id]))}</code></p><p>Correct answer: <code>${esc(practiceAnswerLabel(q,String(q.answer)))}</code></p><p>${esc(q.explanation)}</p></details>`}).join('')}</div><div class="actions"><button id="saveTestJournal">Save reflection to Journal</button><button id="practiceNewTest">Try another test ↗</button></div>`:(()=>{const q=practiceQuestion(test.qids[test.index]);return `<div class="test-navigation" role="group" aria-label="Test questions">${test.qids.map((id,i)=>`<button data-test-index="${i}" aria-label="Question ${i+1}${test.answers[id]!==undefined&&test.answers[id]!==''?', answered':''}" ${i===test.index?'aria-current="step"':''}>${i+1}${test.answers[id]!==undefined&&test.answers[id]!==''?' ·':''}</button>`).join('')}</div><p class="learning-hint">Your answers save as you go. Hints and solutions stay hidden until submission.</p><h3>${esc(q.prompt)}</h3><pre class="practice-code"><code>${esc(q.code)}</code></pre>${practiceAnswerInput(q,test.answers[q.id]||'','test')}<p role="alert" id="practiceTestError" class="practice-test-error"></p><div class="actions"><button data-test-index="${Math.max(0,test.index-1)}" ${test.index===0?'disabled':''}>← Previous</button>${test.index<4?`<button data-test-index="${test.index+1}" class="primary">Next question →</button>`:'<button id="practiceSubmitTest" class="primary">Submit my test</button>'}</div>`})()}`}
function practiceSetAnswer(target){if(target.dataset.practiceAnswer==='practice'){const draft=currentPracticeDraft();draft.answer=target.value;draft.checked=false;draft.revealed=false;document.querySelectorAll('#practiceDialog .practice-feedback,#practiceDialog .practice-solution').forEach(el=>el.remove());persistPractice()}else if(target.dataset.practiceAnswer==='test'){const test=activePracticeTest();if(test?.status==='active'){test.answers[test.qids[test.index]]=target.value;persistPractice()}}}
function setupPractice(){document.addEventListener('input',e=>{if(e.target.dataset.practiceAnswer)practiceSetAnswer(e.target)});document.addEventListener('change',e=>{if(e.target.dataset.practiceAnswer)practiceSetAnswer(e.target);if(e.target.id==='practiceTopic'){practiceState.topic=e.target.value;practiceState.draft=null;persistPractice();renderPractice()}});document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.closePractice){$(b.dataset.closePractice).close();renderPractice()}if(b.id==='openPractice'){renderPracticeWindow();$('practiceDialog').showModal()}if(b.id==='openTest'){startPracticeTest();renderTestWindow();$('testDialog').showModal()}if(b.id==='practiceHint'){currentPracticeDraft().hint=!currentPracticeDraft().hint;persistPractice();renderPracticeWindow()}if(b.id==='practiceSolution'){currentPracticeDraft().revealed=!currentPracticeDraft().revealed;persistPractice();renderPracticeWindow()}if(b.id==='practiceCheck'){const d=currentPracticeDraft();if(d.answer===''){toast('Choose or type an answer first.');return}d.checked=true;practiceState.checks.push({id:newId(),qid:d.qid,date:practiceDay(),answer:d.answer,correct:practiceCorrect(practiceQuestion(d.qid),d.answer),helped:d.hint||d.revealed,createdAt:new Date().toISOString()});persistPractice();renderPracticeWindow()}if(b.id==='practiceNext'){const q=shuffledPractice(practicePool().filter(q=>q.id!==currentPracticeDraft().qid),practiceDay()+practiceState.checks.length+newId())[0];practiceState.draft={qid:q.id,answer:'',hint:false,checked:false,revealed:false};persistPractice();renderPracticeWindow()}if(b.dataset.practiceRetry){const id=unresolvedPracticeMistakes()[0];if(id){practiceState.topic=practiceQuestion(id).topic;practiceState.draft={qid:id,answer:'',hint:false,checked:false,revealed:false};persistPractice();renderPracticeWindow();$('practiceDialog').showModal()}}if(b.dataset.testIndex!==undefined){const t=activePracticeTest();if(t?.status==='active'){t.index=Math.max(0,Math.min(4,Number(b.dataset.testIndex)));persistPractice();renderTestWindow()}}if(b.id==='practiceSubmitTest'){const t=activePracticeTest();const missing=t.qids.findIndex(id=>t.answers[id]===undefined||t.answers[id]==='');if(missing>=0){t.index=missing;persistPractice();renderTestWindow();$('practiceTestError').textContent='Answer all five questions before submitting.';return}t.status='submitted';t.score=testScore(t);t.endedAt=new Date().toISOString();persistPractice();renderTestWindow();renderPractice()}if(b.id==='practiceNewTest'){practiceState.activeTestId='';startPracticeTest();renderTestWindow()}if(b.dataset.practiceResult){practiceState.activeTestId=b.dataset.practiceResult;persistPractice();renderTestWindow();$('testDialog').showModal()}if(b.id==='saveTestJournal'){const t=activePracticeTest();$('testDialog').close();showJournalEditor(null,'learning');$('journalEntryDate').value=t.date;$('journalEntryTitle').value='Python check-in · '+PRACTICE_TOPICS[t.topic];$('journalEntryText').value=`I completed a five-question ${PRACTICE_TOPICS[t.topic]} check-in. Score: ${t.score}/5.\n\nTopics to revisit:\n${t.qids.filter(id=>!practiceCorrect(practiceQuestion(id),t.answers[id])).map(id=>'• '+practiceQuestion(id).prompt+' — '+practiceQuestion(id).explanation).join('\n')||'All five answers were correct. Try explaining the reasoning without notes.'}\n\nMy reflection:\n`;resetLearningPreview('journalEntryText')}});for(const id of ['practiceDialog','testDialog'])$(id).addEventListener('close',()=>{if(view==='practice')renderPractice()})}
